    let cost: number;
    if (wantWorker && myRes >= 4) {
      toSpawn = "worker";
      cost = 4;
    } else if (myRes >= 8) {
      toSpawn = "melee";
      cost = 8;
    } else {
      continue;
    }
    if (myRes < cost) continue;
    const sr = spawnUnit(b.id, toSpawn);
    if (!isError(sr)) {
      myRes -= cost;
    }
