// 走向 (tx, ty) 的某个 plain 相邻格
function moveToAdjOf(
  w: { id: number; x: number; y: number },
  tx: number,
  ty: number
): void {
  let ax = tx;
  let ay = ty;
  let bestD = 999;
  for (let dx = -1; dx <= 1; dx += 1) {
    for (let dy = -1; dy <= 1; dy += 1) {
      if (dx === 0 && dy === 0) continue;
      const nx = tx + dx;
      const ny = ty + dy;
      if (getTerrainAt(nx, ny) !== "plain") continue;
      const d = getRange(w.x, w.y, nx, ny);
      if (d < bestD) { bestD = d; ax = nx; ay = ny; }
    }
  }
  if (bestD < 999) {
    moveTo(w.id, ax, ay);
  }
}

// 走向最近基地的某个 plain 相邻格
function moveToBaseAdj(
  w: { id: number; x: number; y: number },
  bases: ReadonlyArray<{ x: number; y: number }>
): void {
  let bx = 0;
  let by = 0;
  let bestD = 999;
  for (let i = 0; i < bases.length; i += 1) {
    const b = bases[i];
    const d = getRange(w.x, w.y, b.x, b.y);
    if (d < bestD) { bestD = d; bx = b.x; by = b.y; }
  }
  moveToAdjOf(w, bx, by);
}
```

